// Curated additions, verified against project documentation and CoinGecko IDs.
// Project utility is distinct from the confidentiality of its traded token.
const item=(roles,mode,privacy,limits,security,goal,next,sources)=>({roles,mode,privacy,limits,security,goal,next,sources,status:'Project sources reviewed · token and application privacy differ',reviewed:'2026-09-18'});
export const ecosystem={
'oasis-network':item(['Confidential computing','Private smart contracts'],'Application-dependent','Oasis offers hardware-backed confidential execution and confidential smart contracts. Its privacy role covers application data and computation.','ROSE ownership or transfer does not automatically provide confidential application behavior. Public interfaces and application disclosure policies still matter.','Trusted execution environments depend on hardware isolation, attestation and key management; application code adds separate risks.','Enable private, verifiable applications across finance, identity and AI.','The stated direction combines on-chain confidentiality with off-chain compute and programmable policies. Product adoption and integration are ongoing goals; this review does not assert new delivery dates.',['https://oasis.net/']),
secret:item(['Confidential computing','Private smart contracts'],'Application-dependent','Secret supports encrypted smart-contract inputs and state and provides confidential computing infrastructure for applications and AI.','Native SCRT and privacy-enabled contract tokens are different. A private application does not make all underlying token movements or metadata private.','Hardware enclaves, attestation, key management and contract access rules are distinct trust assumptions. A malicious application can still disclose data.','Make confidential application services available across networks and to AI developers.','The project emphasizes Secret AI, confidential virtual machines and integrations. Existing contract support is distinguished from the broader ambition to expand confidential AI workloads.',['https://scrt.network/']),
pha:item(['Confidential computing'],'Application-dependent','Phala provides a confidential compute cloud, including GPU trusted execution environments for private AI inference.','Compute confidentiality is not anonymous PHA transfers. An application can disclose outputs, log inputs outside its enclave or identify users at its interface.','Security relies on hardware isolation, remote attestation, correct workload code and operational key handling.','Make private AI and verifiable cloud workloads accessible to developers.','The project direction is broader confidential AI deployment and developer access. The reviewed source does not establish a new dated milestone schedule.',['https://phala.com/']),
'iexec-rlc':item(['Confidential computing','Privacy infrastructure'],'Application-dependent','iExec supplies confidential off-chain computation for on-chain applications, with a focus on protecting sensitive inputs and data use.','RLC transfers and payment records are distinct from protected compute jobs. Confidential execution does not hide everything an application reveals.','Compute-worker execution, hardware protections, application code and data-access permissions are separate security dependencies.','Bring confidentiality to on-chain finance and data-driven applications.','The stated direction includes confidential financial workflows and integrations. Roadmap ambition does not establish that every financial application has shipped or been audited.',['https://iex.ec/']),
aleo:item(['Private smart contracts','Privacy-focused applications'],'Application-dependent','Aleo uses zero-knowledge technology for private programmable activity and markets its platform around private stablecoin payments.','Protection depends on the program and its public/private data choices. Payment recipients and exchange entry or exit can still know identifying information.','Proof systems, program correctness, wallet proving and key security all matter; a private program is not automatically a safe program.','Make private payments and programmable applications usable at scale.','Current positioning emphasizes stablecoin payments and developer adoption. No specific future release date is independently verified here.',['https://aleo.org/']),
'midnight-3':item(['Private smart contracts'],'Application-dependent','Midnight is designed for programmable data protection and selective disclosure, allowing applications to prove facts while limiting exposure of sensitive information.','NIGHT is the ecosystem asset, not a guarantee that its transfers are anonymous. Public-chain representations and application disclosure policies have separate properties.','Privacy depends on proof implementation, application logic, key management and what users choose or are required to disclose.','Support applications that combine confidentiality with selective verification.','Its long-term direction is adoption of data-protecting applications and developer tools. The platform vision must be distinguished from each application’s actual deployment and release status.',['https://midnight.network/']),
'dusk-network':item(['Private smart contracts','Privacy infrastructure'],'Application-dependent','Dusk targets confidential and regulated on-chain finance, including programmable financial infrastructure.','Confidentiality can coexist with authorized disclosure. DUSK token transfers and regulated application records should not be assumed to have identical visibility.','Consensus, proofs, application access control and real-world asset administration create distinct dependencies.','Bring regulated financial assets and activity on-chain while protecting sensitive information.','The project emphasizes financial-market infrastructure and integrations. Institutional adoption and application rollout are objectives, not guaranteed outcomes or dates.',['https://dusk.network/']),
railgun:item(['Privacy infrastructure','Privacy-focused applications'],'Application-dependent','RAILGUN is a smart-contract privacy system using zero-knowledge proofs to support shielded assets and private interactions on public chains.','Holding RAIL does not shield funds. Users must use the privacy system; deposits, withdrawals, timing and external application behavior can expose context.','Proof verification, trusted-setup assumptions, contracts, wallet software and broadcasters require separate scrutiny.','Make private balances, transfers and DeFi interactions practical within public-chain ecosystems.','Documentation provides shielding, unshielding, SDKs and integration tools. The direction is broader private application integration; no new dated delivery promise is established here.',['https://docs.railgun.org/wiki/learn']),
panther:item(['Privacy infrastructure','Privacy-focused applications'],'Application-dependent','Panther describes a zero-knowledge privacy layer with shielded pools and regulated Zones for DeFi. Its documentation explicitly distinguishes the proposed design from current functionality.','ZKP token transfers are not equivalent to private pool activity. Zone operators and disclosure policies affect who can access information.','Proofs, pool contracts, operator permissions and cross-chain interfaces create separate assumptions. A described architecture is not an independently verified deployment.','Enable privacy-enhanced DeFi environments with configurable disclosure and participation rules.','The documentation presents a multi-chain vision and testnet resources and warns that present-tense descriptions may express future intentions. This entry does not label those plans as fully shipped.',['https://docs.pantherprotocol.io/docs']),
nym:item(['Privacy infrastructure','Privacy-focused applications'],'Network-focused','Nym provides a decentralized VPN and mixnet designed to reduce traffic-analysis and communications-metadata exposure. Different connection modes trade speed against protection.','A VPN cannot make public token transfers private or erase information given to a website. Endpoint compromise and identifiable account logins remain relevant.','Relay distribution, routing behavior, client software and traffic-correlation resistance are important assumptions.','Make metadata-resistant internet access practical for everyday users.','Published materials emphasize VPN usability, mixnet improvements, censorship resistance and post-quantum key work. The broader security roadmap should not be treated as complete merely because one phase is released.',['https://nym.com/']),
hopr:item(['Privacy infrastructure'],'Network-focused','HOPR develops privacy-preserving data transport intended to protect communications metadata, rather than simply encrypt message content.','HOPR token activity is distinct from protected network traffic. A destination service or compromised client can still identify a user.','Routing, relay incentives, traffic-analysis resistance and endpoint configuration are separate security dependencies.','Provide a private transport layer that applications can integrate.','The direction is network utility and application integration. Specific future capacity, adoption and release dates are not verified in this review.',['https://hoprnet.org/']),
'orchid-protocol':item(['Privacy infrastructure','Privacy-focused applications'],'Network-focused','Orchid provides decentralized connectivity services and a marketplace model for network resources, including VPN access.','OXT is an ecosystem token; ordinary token transfers are not made anonymous by the VPN service. Provider and destination visibility depend on routing and encryption.','Provider selection, client configuration, payment mechanisms and endpoint security are separate concerns.','Offer usable decentralized network services through an open resource marketplace.','Its broader DePIN direction builds on connectivity services. This review does not infer that every advertised service or expansion is already deployed.',['https://www.orchid.com/']),
sentinel:item(['Privacy infrastructure','Privacy-focused applications'],'Network-focused','Sentinel supplies infrastructure for developers to build decentralized VPN products. Its privacy role is internet connectivity.','The network’s P2P token and VPN traffic have different visibility. Browsing accounts, destination logs and endpoint behavior can still expose identity.','Node operation, VPN protocol choices and application implementation affect protection; decentralization alone does not guarantee anonymity.','Expand an ecosystem of independently operated decentralized VPN applications.','The stated direction is easier dVPN development and network use. No new dated milestone is certified here.',['https://sentinel.co/']),
beldex:item(['Privacy payments','Privacy infrastructure','Privacy-focused applications'],'Layer-dependent','Beldex positions its ecosystem around a privacy-oriented currency and decentralized communication and web services.','Private payments, messaging and browsing are distinct capabilities. One product’s protection must not be assumed for every wallet, application or token representation.','Consensus, service-node behavior, wallet software and individual communication clients need separate review.','Develop a privacy-focused decentralized web spanning payments and communications.','The forward direction is ecosystem integration and practical use of its privacy applications. This review does not certify deployment of every advertised feature or a firm future schedule.',['https://beldex.io/']),
'session-token':item(['Privacy-focused applications','Privacy infrastructure'],'Network-focused','Session Token supports the infrastructure behind Session’s privacy-focused messaging network. The privacy use case is communication, not automatic secrecy of token transfers.','Recipients can disclose messages, and device compromise can expose content. Public token or staking activity is distinct from private messaging.','Client cryptography, message routing, service-node distribution and endpoint security are separate dependencies.','Sustain decentralized messaging infrastructure and its operator incentives.','The stated direction is a usable, sustainable private communications network. Token utility and network participation do not guarantee private returns or a delivery schedule for new app features.',['https://token.getsession.org/']),
status:item(['Privacy-focused applications'],'Network-focused','Status combines a private messenger with a Web3 wallet and browser. Message confidentiality and blockchain transaction confidentiality are different functions.','Using the wallet or browser does not automatically conceal public-chain addresses, balances or dApp transactions. Contacts and endpoint compromise can reveal information.','Messaging protocols, device key storage and each connected dApp have independent security properties.','Provide an accessible interface for private communication and self-controlled Web3 activity.','The direction is a more integrated messaging, wallet and application experience. This review does not establish a new dated privacy milestone.',['https://status.app/']),
automata:item(['Confidential computing','Privacy infrastructure'],'Application-dependent','Automata develops verifiable-machine and attestation infrastructure for Web3 and AI, including hardware-based trusted execution.','Attesting how software runs does not by itself make ATA transfers private or ensure that an application hides its outputs.','Hardware trust, attestation verification, code measurement and software configuration are distinct security dependencies.','Let applications verify execution and use confidential computing infrastructure.','The stated direction is broader verifiable computation across Web3 and AI. Future integrations are not treated as universally delivered or independently audited.',['https://www.ata.network/']),
'lit-protocol':item(['Privacy infrastructure','Confidential computing'],'Application-dependent','Lit provides programmable cryptographic access and signing infrastructure for applications, including policies governing access to protected data.','Access-controlled decryption does not make LITKEY transfers private. Policy design determines who can decrypt data or authorize operations.','Distributed key operations, node execution, authentication and access rules must all be assessed; incorrect permissions can defeat encryption.','Give applications programmable control over cryptographic keys and protected data.','The project direction is developer adoption of programmable security and data-access services. No new dated release commitment is verified here.',['https://www.litprotocol.com/']),
'threshold-network-token':item(['Privacy infrastructure'],'Application-dependent','Threshold is included for distributed cryptographic infrastructure. Its current website emphasizes Bitcoin finance and threshold-secured services, rather than anonymous T-token payments.','Threshold signing and bridging are not equivalent to transaction confidentiality. Bitcoin and public-chain token activity can remain observable.','Signer thresholds, operator coordination, custody assumptions and bridge contracts are distinct security boundaries.','Provide decentralized cryptographic services, with a current focus on Bitcoin financial access.','Current positioning centers on Bitcoin finance. This is adjacent infrastructure coverage, not a claim that the project is delivering a new privacy coin or a dated confidential-payment upgrade.',['https://www.threshold.network/']),
zama:item(['Confidential computing','Private smart contracts','Privacy infrastructure'],'Application-dependent','Zama uses fully homomorphic encryption to compute on encrypted values and support confidential assets and applications on public chains.','Encrypted amounts do not necessarily hide participants: the project describes explorer support with visible senders and recipients. Ordinary ZAMA transfers are distinct from confidential application assets.','Encryption parameters, key management, authorized decryption and application permissions are separate dependencies.','Make confidential payments, asset issuance and financial applications practical on public blockchains.','The stated direction is broader institutional and developer adoption across payments, tokenization and DeFi. Existing product descriptions are not promises that every future integration is complete.',['https://www.zama.org/']),
aztec:item(['Private smart contracts','Privacy infrastructure'],'Application-dependent','Aztec is an Ethereum layer-two network designed for programmable privacy and client-side proofs, allowing applications to choose public and private execution.','The confidentiality of an application depends on its code and disclosure boundaries. Token ownership and bridge activity do not automatically inherit private execution.','Proof correctness, sequencing, rollup contracts, client-side key handling and application logic are distinct dependencies.','Make composable private applications practical within the Ethereum ecosystem.','The project emphasizes developer tooling, private application composition and decentralized operation. No additional dated rollout is certified by this review.',['https://aztec.network/'])
};
export const curatedIds=Object.keys(ecosystem);
export const supplementalIds=[...new Set(['beam','zephyr-protocol','dash',...curatedIds])];
export const coverageScope='CoinGecko privacy-coins category + curated privacy ecosystem';
export const ecosystemProfiles=Object.fromEntries(Object.entries(ecosystem).map(([id,r])=>[id,{mode:r.mode,protocol:r.privacy,goal:r.goal,risks:r.limits+' '+r.security,economics:'Market values are provider-reported. Token utility, issuance, unlocks and staking incentives require separate assessment; application adoption is not a promise of token returns.',sources:r.sources,reviewed:r.reviewed}]));
// Categories describe documented project focus, not verified deployment or token privacy.
